import{document}from"../../build/spruceStdlib.min.js";import{sitemap}from"./sitemap.min.js";function bannerDocument(body){return`<div id="banner">
	<div id="banner-small"></div>
	<div id="banner-large"></div>
</div>

<div id="content-container">
	<div id="content">
		${document(body)}
	</div>
</div>`}function carousel(...blocks){return`
		<div class="carousel">
			<div class="carousel-content">
				${blocks.map(block=>`<div class="carousel-entry">${block}</div>`).join("")}
			</div>

			<div class="carousel-dots">
				${'<div class="carousel-dot"><div class="fill"></div></div>'.repeat(blocks.length)}
			</div>
		</div>
	`}function clickTap(clickText,tapText){return`<span class="click-tap"><span>${clickText}</span><span>${tapText}</span></span>`}function galleryBlock(...data){if(data.length%2!=0)throw new Error("Invalid number of arguments");let a='<div class="gallery-block">';for(let t=0;t<data.length;t+=2){var e=data[t],i=data[t+1];a+=`
		<div class="gallery-image-${i}-${i}">
			<img src="/graphics/general-icons/placeholder.png" data-src="/gallery/thumbnails/${e}.webp" data-image-id="${e}" />
		</div>`}return a+"</div>"}function imageLinks(data){return`<div style="display: flex; justify-content: center; width: 100%;">
	<div class="image-links">${data.map(item=>{var a=resolveUrl((item="string"==typeof item?{url:item}:item).url),e=a.split(".")[0].split("/"),e=e[e.length-1];if(void 0===item.name&&void 0===sitemap[a]&&void 0===item.coverPath)throw new Error(a+" is not in sitemap!");var i,t=item.name??sitemap[a].title;return item.forCard?`
				<a href="${i=a.slice(0,a.lastIndexOf("/"))}/?card=${e}" data-card-id="${e}" class="image-link">
					<img src="/graphics/general-icons/placeholder.png" data-src="${item.coverPath??i+`/cards/${e}/cover.webp`}" alt="${t}" tabindex="1" />
					
					<p class="image-link-subtext">${t}</p>
				</a>
			`:(i=a.includes(".")?a.slice(0,a.lastIndexOf("/"))+"/cover.webp":a+"/cover.webp",`
		<a href="${a}"${item.inNewTab?' data-in-new-tab="1"':""} class="image-link">
			<img src="/graphics/general-icons/placeholder.png" data-src="${item.coverPath??i}" alt="${t}" tabindex="1" />
			
			<p class="image-link-subtext">${t}</p>
		</a>`)}).join("")}</div>
</div>`}function card(id,name,body){return name?`<div id="${id}-card" class="card"><h1 class="heading-text">${name}</h1>${body}</div>`:`<div id="${id}-card" class="card">${body}</div>`}function externalCard(id){return`<div id="${id}-card" class="card external-card"></div>`}function debug(body){return`<div class="DEBUG">${body}</div>`}function center(body){return`<p class="body-text center-if-needed"><span>${body}</span></p>`}function resolveUrl(url){var a;return url.startsWith("http")||(a=(a=globalThis.filePath.replace(/^.+?cruzgodar\.github\.io/,"")).slice(0,a.lastIndexOf("/")),"/"===url[0])?url:a+"/"+url}export{bannerDocument,carousel,clickTap,galleryBlock,imageLinks,card,externalCard,debug,center};